pub const fn aphelios_p1(ctx: &Ctx) -> f32 {
    4f32 * ctx.level
}

pub const fn aphelios_p2(ctx: &Ctx) -> f32 {
    0.1 * ctx.bonus_ad
}

pub const fn aphelios_p3(ctx: &Ctx) -> f32 {
    2f32 + 0.3 * (-1f32 + ctx.level)
}

pub const fn aphelios_p4(ctx: &Ctx) -> f32 {
    (match ctx.level as u8 {
        ..=1 => 75f32,
        2.. => 100f32,
    }) + 1.1 * ctx.steelcaps_effect
}

pub const fn aphelios_p5(ctx: &Ctx) -> f32 {
    0.23 * ctx.steelcaps_effect
}

pub const fn aphelios_p6(ctx: &Ctx) -> f32 {
    match ctx.level as u8 {
        ..=1 => 0f32,
        2 => 15f32,
        3 => 28.5,
        4 => 40.5,
        5 => 51f32,
        6 => 60f32,
        7 => 67.5,
        8 => 73.5,
        9 => 78.5,
        10 => 83.5,
        11 => 88.5,
        12 => 93.5,
        13 => 98.5,
        14 => 103.5,
        15 => 108.5,
        16 => 113.5,
        17 => 118.5,
        18 => 123.5,
        19 => 128.5,
        20 => 133.5,
        21.. => 138.5,
    }
}

pub const fn aphelios_p7(ctx: &Ctx) -> f32 {
    1.385 * ctx.steelcaps_effect
}

