pub const fn ekko_p(ctx: &Ctx) -> f32 {
    (match ctx.level as u8 {
        ..=1 => 30f32,
        2 => 40f32,
        3 => 50f32,
        4 => 60f32,
        5 => 70f32,
        6 => 80f32,
        7 => 85f32,
        8 => 90f32,
        9 => 95f32,
        10 => 100f32,
        11 => 105f32,
        12 => 110f32,
        13 => 115f32,
        14 => 120f32,
        15 => 125f32,
        16 => 130f32,
        17 => 135f32,
        18 => 140f32,
        19 => 145f32,
        20.. => 150f32,
    }) + 0.8 * ctx.ability_power
}

pub const fn ekko_q1min(ctx: &Ctx) -> f32 {
    5f32 * (16f32 + 0.06 * ctx.ability_power + 3f32 * (-1f32 + ctx.q_level))
}

pub const fn ekko_qmax(ctx: &Ctx) -> f32 {
    40f32 * (2f32 + 0.0225 * ctx.ability_power + ctx.q_level)
}

pub const fn ekko_q1max(ctx: &Ctx) -> f32 {
    5f32 * (8f32 + 0.12 * ctx.ability_power + 5f32 * (-1f32 + ctx.q_level))
}

pub const fn ekko_e(ctx: &Ctx) -> f32 {
    25f32 * (1f32 + 0.016 * ctx.ability_power + ctx.e_level)
}

pub const fn ekko_r(ctx: &Ctx) -> f32 {
    200f32 + 1.75 * ctx.ability_power + 150f32 * (-1f32 + ctx.r_level)
}

