pub const fn kled_p1(ctx: &Ctx) -> f32 {
    match ctx.level as u8 {
        ..=1 => 400f32,
        2 => 442.35,
        3 => 486.76,
        4 => 533.24,
        5 => 581.76,
        6 => 632.35,
        7 => 685f32,
        8 => 739.71,
        9 => 796.47,
        10 => 855.29,
        11 => 916.18,
        12 => 979.12,
        13 => 1044.12,
        14 => 1111.18,
        15 => 1180.29,
        16 => 1251.47,
        17 => 1324.71,
        18 => 1400f32,
        19 => 1477.35,
        20.. => 1556.76,
    }
}

