pub const fn sett_p(ctx: &Ctx) -> f32 {
    5f32 * (0.11 * ctx.bonus_ad + ctx.level)
}

pub const fn sett_qmin(ctx: &Ctx) -> f32 {
    10f32
        * (ctx.q_level
            + 0.001
                * ctx.enemy_max_health
                * (1f32
                    + ctx.attack_damage
                        * (0.01 + 0.005 * (-1f32 + ctx.q_level))))
}

pub const fn sett_qmax(ctx: &Ctx) -> f32 {
    20f32
        + 20f32 * (-1f32 + ctx.q_level)
        + ctx.enemy_max_health
            * (0.02
                + 0.01
                    * ctx.attack_damage
                    * (0.02 + 0.01 * (-1f32 + ctx.q_level)))
}

pub const fn sett_w(ctx: &Ctx) -> f32 {
    80f32
        + 20f32 * (-1f32 + ctx.w_level)
        + ctx.stacks * (0.25 + 0.0025 * ctx.bonus_ad)
}

pub const fn sett_e(ctx: &Ctx) -> f32 {
    10f32 * (5f32 + 0.06 * ctx.attack_damage + 2f32 * (-1f32 + ctx.e_level))
}

pub const fn sett_rmin(ctx: &Ctx) -> f32 {
    50f32
        + 0.3 * ctx.bonus_ad
        + 25f32 * (-1f32 + ctx.r_level)
        + ctx.bonus_health * (0.1 + 0.0125 * (-1f32 + ctx.r_level))
}

pub const fn sett_rmax(ctx: &Ctx) -> f32 {
    200f32
        + 1.2 * ctx.bonus_ad
        + 100f32 * (-1f32 + ctx.r_level)
        + ctx.bonus_health * (0.4 + 0.05 * (-1f32 + ctx.r_level))
}

