pub const fn zeri_p1(ctx: &Ctx) -> f32 {
    10f32
        + 0.03 * ctx.ability_power
        + 15f32 * (-1f32 + ctx.level) * (0.7025 + 0.0175 * (-1f32 + ctx.level))
            / 17f32
}

pub const fn zeri_p2(ctx: &Ctx) -> f32 {
    0.2 * ctx.ability_power
}

pub const fn zeri_p3(ctx: &Ctx) -> f32 {
    75f32 + 1.1 * ctx.ability_power + 5f32 * (-1f32 + ctx.level)
}

pub const fn zeri_p4(ctx: &Ctx) -> f32 {
    ctx.enemy_max_health * (0.01 + 0.0059 * (-1f32 + ctx.level))
}

pub const fn zeri_p5(ctx: &Ctx) -> f32 {
    5f32 * (14f32 + ctx.level)
}

pub const fn zeri_p6(ctx: &Ctx) -> f32 {
    ctx.enemy_max_health * (0.01 + 0.0059 * (-1f32 + ctx.level))
}

pub const fn zeri_p7(_: &Ctx) -> f32 {
    0f32
}

pub const fn zeri_q1(ctx: &Ctx) -> f32 {
    7.23 + 1.31 * (-1f32 + ctx.q_level)
        + ctx.attack_damage * (0.3351 + 0.0066 * (-1f32 + ctx.q_level))
}

pub const fn zeri_q2(ctx: &Ctx) -> f32 {
    3.14 + 0.57 * (-1f32 + ctx.q_level)
        + ctx.attack_damage * (0.1457 + 0.0029 * (-1f32 + ctx.q_level))
}

pub const fn zeri_q3(ctx: &Ctx) -> f32 {
    44f32
        + 8f32 * (-1f32 + ctx.q_level)
        + ctx.attack_damage * (2.04 + 0.04 * (-1f32 + ctx.q_level))
}

pub const fn zeri_q4(ctx: &Ctx) -> f32 {
    50.6 + 9.2 * (-1f32 + ctx.q_level)
        + ctx.attack_damage * (2.346 + 0.046 * (-1f32 + ctx.q_level))
}

pub const fn zeri_q5(ctx: &Ctx) -> f32 {
    22f32
        + 4f32 * (-1f32 + ctx.q_level)
        + ctx.attack_damage * (1.02 + 0.02 * (-1f32 + ctx.q_level))
}

pub const fn zeri_w1(ctx: &Ctx) -> f32 {
    45f32
        + 0.75 * ctx.ability_power
        + 1.8 * ctx.attack_damage
        + 60f32 * (-1f32 + ctx.w_level)
}

pub const fn zeri_w2(ctx: &Ctx) -> f32 {
    49.5 + 0.825 * ctx.ability_power
        + 1.98 * ctx.attack_damage
        + 66f32 * (-1f32 + ctx.w_level)
}

pub const fn zeri_w3(ctx: &Ctx) -> f32 {
    30f32
        + 1.2 * ctx.attack_damage
        + 40f32 * (-1f32 + ctx.w_level)
        + ctx.ability_power / 2f32
}

pub const fn zeri_emin(ctx: &Ctx) -> f32 {
    5f32 * (15f32 + ctx.e_level)
}

pub const fn zeri_emax(ctx: &Ctx) -> f32 {
    2f32 * (10f32 + 0.1 * ctx.ability_power + ctx.e_level)
}

pub const fn zeri_r(ctx: &Ctx) -> f32 {
    150f32
        + 1.1 * ctx.ability_power
        + 0.6 * ctx.bonus_ad
        + 100f32 * (-1f32 + ctx.r_level)
}

